import{_ as t,o as a,c as o,a2 as e}from"./chunks/framework.DsJhYLZ-.js";const h=JSON.parse('{"title":"ReAct: Synergizing Reasoning and Acting in Language Models","description":"","frontmatter":{"title":"ReAct: Synergizing Reasoning and Acting in Language Models","authors":"Shunyu Yao(姚顺雨), Jeffrey Zhao, Dian Yu, Nan Du, Izhak Shafran, Karthik Narasimhan, Yuan Cao(Princeton + Google Brain)","source":"ICLR 2023 · arXiv:2210.03629","status":"读完","date":"2026-07-28","link":"https://arxiv.org/abs/2210.03629","tags":["LLM","Agent","Reasoning","Prompting","CoT"]},"headers":[],"relativePath":"ai/agent/yao-2023-react.md","filePath":"ai/agent/yao-2023-react.md","lastUpdated":1786297935000}'),s={name:"ai/agent/yao-2023-react.md"};function i(r,n,l,g,c,u){return a(),o("div",null,[...n[0]||(n[0]=[e(`<h1 id="react-synergizing-reasoning-and-acting-in-language-models" tabindex="-1">ReAct: Synergizing Reasoning and Acting in Language Models <a class="header-anchor" href="#react-synergizing-reasoning-and-acting-in-language-models" aria-label="Permalink to &quot;ReAct: Synergizing Reasoning and Acting in Language Models&quot;">​</a></h1><blockquote><p><strong>一句话总结</strong>:把大模型的&quot;推理(想)&quot;和&quot;行动(调工具)&quot;交织进同一个循环——想一步→查一步→再想,让推理有真实事实兜底、行动有计划指引。它是今天几乎所有 AI Agent 的思想原型。 🔗 <strong>相关实操</strong>:Stage 1:手写 ReAct Loop · Stage 0:手写 Function Calling · 名词见<a href="/blog/ai/llm-basics/glossary.html">大模型基础名词词典</a></p></blockquote><h2 id="背景与动机" tabindex="-1">背景与动机 <a class="header-anchor" href="#背景与动机" aria-label="Permalink to &quot;背景与动机&quot;">​</a></h2><ul><li>在此之前,LLM 的两种能力被<strong>分开研究</strong>: <ul><li><strong>Reasoning 推理</strong>(如 Chain-of-Thought):只在&quot;脑子里&quot;空想,不接触外部世界 → 一旦某事实记错,后续全盘皆错(<strong>幻觉 + 错误传播</strong>)。</li><li><strong>Acting 行动</strong>(如动作计划生成):闷头做,不会边做边想、不会处理意外。</li></ul></li><li>核心洞察:<strong>人类做事时&quot;想&quot;和&quot;做&quot;本就是交织的</strong>——查资料时会想该搜什么→搜→看结果→纠偏再搜。ReAct 就是把这个循环搬给大模型。</li></ul><h2 id="核心方法-主要观点" tabindex="-1">核心方法 / 主要观点 <a class="header-anchor" href="#核心方法-主要观点" aria-label="Permalink to &quot;核心方法 / 主要观点&quot;">​</a></h2><p><strong>Thought → Action → Observation 交替循环</strong>(全文灵魂):</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Thought:  我需要知道 X,应该先查 Y          ← 推理(内部,不与外界交互)</span></span>
<span class="line"><span>Action:   search[Y]                        ← 行动(调外部工具/API)</span></span>
<span class="line"><span>Observation: (Y 的搜索结果返回)            ← 环境反馈(外部真实事实)</span></span>
<span class="line"><span>Thought:  结果提到 Z 但没说 X,再查 Z</span></span>
<span class="line"><span>Action:   search[Z]</span></span>
<span class="line"><span>Observation: ...</span></span>
<span class="line"><span>Thought:  够了</span></span>
<span class="line"><span>Action:   finish[W]                         ← 结束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><strong>Thought</strong>:组织思路、拆计划、纠偏,不与外界交互 → 让推理&quot;引导&quot;行动。</li><li><strong>Action</strong>:真正调用外部。HotpotQA 里动作空间极简,仅三个:<code>search[实体]</code>、<code>lookup[关键词]</code>、<code>finish[答案]</code>。</li><li><strong>Observation</strong>:环境返回的真实反馈,把模型拉回现实 → 让行动&quot;喂事实&quot;给推理,治幻觉。</li><li>两者<strong>相互补台</strong>,即标题的 <strong>Synergizing(协同)</strong>。</li></ul><h2 id="关键结论" tabindex="-1">关键结论 <a class="header-anchor" href="#关键结论" aria-label="Permalink to &quot;关键结论&quot;">​</a></h2><h3 id="实验结果" tabindex="-1">实验结果 <a class="header-anchor" href="#实验结果" aria-label="Permalink to &quot;实验结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务类型</th><th>数据集</th><th>ReAct 做法</th><th>结果</th></tr></thead><tbody><tr><td>知识密集问答/事实核查</td><td>HotpotQA、Fever</td><td>靠 Wikipedia API 边查边推理</td><td>显著压制 CoT 的幻觉与错误传播,轨迹更像人、更可解释</td></tr><tr><td>交互式决策</td><td>ALFWorld(文字家务)、WebShop(网购)</td><td>边想边操作环境</td><td>比模仿学习/RL 基线<strong>绝对成功率高 34% / 10%</strong>,仅用 <strong>1~2 个示例</strong></td></tr></tbody></table><ul><li>最惊人处:<strong>仅 1~2 个 in-context 示例(不训练)</strong> 就打过需要大量训练的 RL 方法。</li></ul><h3 id="react-vs-cot-的本质差别" tabindex="-1">ReAct vs CoT 的本质差别 <a class="header-anchor" href="#react-vs-cot-的本质差别" aria-label="Permalink to &quot;ReAct vs CoT 的本质差别&quot;">​</a></h3><ul><li><strong>结构</strong>:CoT 和 ReAct 都会&quot;一步步推理&quot;,但 <strong>CoT 每步只能靠模型自己记住的知识(闭卷)</strong>,ReAct 每隔几步能去外部捞真实事实(<strong>开卷</strong>)。</li><li><strong>各自失败模式(论文的诚实之处)</strong>: <ul><li><strong>CoT 的病 = 幻觉</strong>:想得流畅但事实是编的;自由度高但易一本正经胡说。</li><li><strong>ReAct 的病 = 卡死/被检索绑架</strong>:搜索没用时会打转,或过度依赖搜到的信息、不敢用自身推理;更实事求是但更死板。</li></ul></li><li><strong>最佳方案 = 两者结合(ReAct + CoT-SC)</strong>:先 ReAct 边查边推理;设定步数内答不出 → 回退 CoT 自采样(self-consistency)用内部知识兜底。&quot;<strong>能查就查,查不到就靠想</strong>&quot;。</li></ul><p><strong>经典例子(Figure 1)</strong>:问&quot;除了 Apple Remote,还有什么设备能控制它最初设计交互的程序?&quot;</p><ul><li>CoT 凭记忆瞎编答 <code>iPod</code>(错,幻觉,无纠错机制)。</li><li>ReAct:search[Apple Remote]→查到控制 Front Row→search[Front Row]→查到可由键盘功能键控制→<code>finish[keyboard function keys]</code>(对)。</li></ul><h2 id="对我的启发-可迁移" tabindex="-1">对我的启发 / 可迁移 <a class="header-anchor" href="#对我的启发-可迁移" aria-label="Permalink to &quot;对我的启发 / 可迁移&quot;">​</a></h2><ul><li>它是今天几乎所有 <strong>AI Agent</strong> 的思想原型——工具调用型 Agent(包括能调工具的助手)底层循环就是 ReAct 的 Thought-Action-Observation。</li><li>证明了 <strong>&quot;给模型外部工具 + 让它边想边用&quot; 比 &quot;把知识全塞进模型脑子&quot; 更可靠</strong>。</li><li><strong>可解释性</strong>:每步 Thought 都写出来,人能看懂它为什么这么做、错在哪 → 对信任与调试极重要。</li><li>一句话记忆:<strong>CoT 让模型会想,ReAct 让模型边想边和世界核对。CoT 天花板是模型记住多少,ReAct 天花板是它能接触多少工具。</strong></li></ul><h2 id="笔记与摘录" tabindex="-1">笔记与摘录 <a class="header-anchor" href="#笔记与摘录" aria-label="Permalink to &quot;笔记与摘录&quot;">​</a></h2><ul><li>摘要金句:&quot;reasoning traces help the model induce, track, and update action plans as well as handle exceptions, while actions allow it to interface with external sources ... to gather additional information.&quot;</li><li>待深挖:ReAct + CoT-SC 的具体回退阈值与切换策略;WebShop/ALFWorld 的动作空间设计。</li></ul>`,20)])])}const p=t(s,[["render",i]]);export{h as __pageData,p as default};
